INSERT INTO ent_equipment (
                id, entity_type_code, model_id, name, code, tenant_id, creator,
                tree_path, sort, status, deleted, custom_fields
            )
            OVERRIDING SYSTEM VALUE
            SELECT
                v.id,
                'equipment',
                m.id,
                v.name,
                v.code,
                1,
                'seed',
                v.tree_path,
                v.sort,
                1,
                false,
                v.custom_fields::jsonb
