              ON m.code = v.model_code
             AND m.entity_type_code = 'equipment'
             AND m.deleted = false
             AND m.tenant_id = 1
            ON CONFLICT (id) DO UPDATE SET
                model_id = EXCLUDED.model_id,
                name = EXCLUDED.name,
                code = EXCLUDED.code,
                tree_path = EXCLUDED.tree_path,
                sort = EXCLUDED.sort,
